// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 fundAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fundAmount);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool revertedWithdraw;
        try c.withdraw(0) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(afterDeposits == beforeDeposits
            && afterBalance >= beforeBalance);
    }

    function testFuzz_run(uint256 fundAmount) public {
        _run(fundAmount);
    }

    receive() external payable {}
}
